using System.Security.Cryptography;using BusinessPartnerPortal.Api.Common;using BusinessPartnerPortal.Api.Data;using BusinessPartnerPortal.Api.Domain;using BusinessPartnerPortal.Api.Oracle;using BusinessPartnerPortal.Api.Security;using Microsoft.EntityFrameworkCore;
namespace BusinessPartnerPortal.Api.Features.Invoices;
public static class InvoiceEndpoints{
 public static IEndpointRouteBuilder MapInvoiceEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/v1/invoices").RequireAuthorization().WithTags("Invoices");
  g.MapGet("/my",async(CurrentUser current,AppDbContext db,CancellationToken ct)=>{await current.DemandAsync("INVOICE.VIEW_OWN",ct);var vendorId=await current.GetVendorIdAsync(ct)??throw new ApiException(403,"Vendor account mapping is missing.");var rows=await db.Invoices.Where(x=>x.VendorId==vendorId&&x.DeletedAt==null).OrderByDescending(x=>x.UpdatedAt).Select(x=>new{x.Id,x.InvoiceNumber,x.InvoiceDate,x.InvoiceAmount,x.Status,x.IntegrationStatus,x.SubmissionDate,x.UpdatedAt,x.PoNumber,x.GrnNumbers,x.InvoiceType}).ToListAsync(ct);return Results.Ok(rows.Select(x=>new{x.Id,x.InvoiceNumber,x.InvoiceDate,x.InvoiceAmount,x.Status,x.IntegrationStatus,x.SubmissionDate,x.UpdatedAt,x.PoNumber,grnNumbers=(x.GrnNumbers??"").Split(',',StringSplitOptions.RemoveEmptyEntries),x.InvoiceType}));});
  g.MapGet("/{id:guid}",async(Guid id,CurrentUser current,AppDbContext db,CancellationToken ct)=>{var vendorId=await current.GetVendorIdAsync(ct);var x=await db.Invoices.FirstOrDefaultAsync(x=>x.Id==id&&(current.IsAdmin||x.VendorId==vendorId),ct)??throw new ApiException(404,"Invoice not found.");return Results.Ok(new{x.Id,x.InvoiceNumber,x.InvoiceDate,x.InvoiceAmount,x.PoNumber,grnNumbers=(x.GrnNumbers??"").Split(',',StringSplitOptions.RemoveEmptyEntries),x.InvoiceType,x.Status,x.IntegrationStatus});});
  g.MapGet("/{id:guid}/history",async(Guid id,CurrentUser current,AppDbContext db,CancellationToken ct)=>{var vendorId=await current.GetVendorIdAsync(ct);var exists=await db.Invoices.AnyAsync(x=>x.Id==id&&(current.IsAdmin||x.VendorId==vendorId),ct);if(!exists)throw new ApiException(404,"Invoice not found.");return Results.Ok(await db.InvoiceStatusHistory.Where(x=>x.InvoiceId==id).OrderBy(x=>x.ChangedAt).ToListAsync(ct));});
  g.MapPost("/draft",async(HttpRequest r,CurrentUser c,AppDbContext db,OracleService o,IConfiguration cfg,ILoggerFactory lf,CancellationToken ct)=>await Save(r,c,db,o,cfg,lf.CreateLogger("Invoice"),true,null,ct)).DisableAntiforgery();
  g.MapPost("/",async(HttpRequest r,CurrentUser c,AppDbContext db,OracleService o,IConfiguration cfg,ILoggerFactory lf,CancellationToken ct)=>await Save(r,c,db,o,cfg,lf.CreateLogger("Invoice"),false,null,ct)).DisableAntiforgery();
  g.MapPost("/{id:guid}/resubmit",async(Guid id,HttpRequest r,CurrentUser c,AppDbContext db,OracleService o,IConfiguration cfg,ILoggerFactory lf,CancellationToken ct)=>await Save(r,c,db,o,cfg,lf.CreateLogger("Invoice"),false,id,ct)).DisableAntiforgery();return app;}
 static async Task<IResult> Save(HttpRequest request,CurrentUser current,AppDbContext db,OracleService oracle,IConfiguration config,ILogger log,bool draft,Guid? resubmitId,CancellationToken ct){await current.DemandAsync(resubmitId is null?"INVOICE.CREATE":"INVOICE.RESUBMIT",ct);var vendorId=await current.GetVendorIdAsync(ct)??throw new ApiException(403,"Vendor account mapping is missing.");var oracleRaw=await db.Vendors.Where(x=>x.Id==vendorId).Select(x=>x.OracleVendorId).FirstOrDefaultAsync(ct);if(!decimal.TryParse(oracleRaw,out var oracleVendorId))throw new ApiException(409,"Oracle vendor mapping is missing or invalid.");if(!request.HasFormContentType)throw new ApiException(400,"multipart/form-data is required.");var f=await request.ReadFormAsync(ct);var poNumber=f["poNumber"].FirstOrDefault()?.Trim()??"";var grnNumbers=f["grnNumbers"].Select(x=>x?.Trim()??"").Where(x=>x.Length>0).Distinct(StringComparer.OrdinalIgnoreCase).ToList();var number=f["invoiceNumber"].FirstOrDefault()?.Trim()??"";var type=(f["invoiceType"].FirstOrDefault()??"GOODS").Trim().ToUpperInvariant();var date=DateOnly.TryParse(f["invoiceDate"].FirstOrDefault(),out var d)?d:(DateOnly?)null;var amount=decimal.TryParse(f["invoiceAmount"].FirstOrDefault(),out var a)?a:0m;if(!draft&&(poNumber.Length==0||number.Length==0||date is null||amount<=0||grnNumbers.Count==0))throw new ApiException(400,"PO, at least one GRN, invoice number, invoice date and positive amount are required.");if(type!="GOODS"&&type!="SERVICE")throw new ApiException(400,"Invoice type must be GOODS or SERVICE.");
  if(poNumber.Length>0){var oracleRows=await oracle.GetPoGrnsAsync(oracleVendorId,poNumber,ct);if(oracleRows.Count==0)throw new ApiException(400,"PO is not available for this vendor in Oracle.");foreach(var g in grnNumbers){var row=oracleRows.FirstOrDefault(x=>string.Equals(x.GrnNumber,g,StringComparison.OrdinalIgnoreCase));if(row is null)throw new ApiException(400,$"GRN {g} does not belong to the selected PO/vendor.");var inspection=(row.InspectionStatus??"").ToUpperInvariant();if(inspection is "PENDING" or "PENDING QC" or "PENDING_QC" or "AWAITING INSPECTION" or "NOT RECEIVED")throw new ApiException(409,$"GRN {g} is Pending with QC and cannot be invoiced yet.");if((row.QuantityAvailableToInvoice??row.GrnReceivedQuantity??0)<=0)throw new ApiException(409,$"GRN {g} has no available quantity to invoice.");}}
  var duplicate=await db.Invoices.AnyAsync(x=>x.VendorId==vendorId&&x.DeletedAt==null&&x.InvoiceNumber.ToLower()==number.ToLower()&&(!resubmitId.HasValue||x.Id!=resubmitId.Value),ct);if(number.Length>0&&duplicate)throw new ApiException(409,"This invoice number already exists for the vendor.");var invoiceFile=f.Files.GetFile("invoiceFile");var dcFile=f.Files.GetFile("deliveryChallanFile");if(!draft&&invoiceFile is null&&resubmitId is null)throw new ApiException(400,"Invoice attachment is required.");if(!draft&&type=="GOODS"&&dcFile is null&&resubmitId is null)throw new ApiException(400,"Receipted Delivery Challan is mandatory for goods invoices.");ValidateFile(invoiceFile,config);ValidateFile(dcFile,config);
  await using var tx=await db.Database.BeginTransactionAsync(ct);var now=DateTimeOffset.UtcNow;Invoice inv;string? old=null;if(resubmitId.HasValue){inv=await db.Invoices.FirstOrDefaultAsync(x=>x.Id==resubmitId.Value&&x.VendorId==vendorId,ct)??throw new ApiException(404,"Invoice not found.");if(inv.Status!="RETURNED")throw new ApiException(409,"Only returned invoices can be resubmitted.");old=inv.Status;inv.InvoiceNumber=number.Length>0?number:inv.InvoiceNumber;inv.InvoiceDate=date??inv.InvoiceDate;if(amount>0)inv.InvoiceAmount=amount;if(poNumber.Length>0)inv.PoNumber=poNumber;if(grnNumbers.Count>0)inv.GrnNumbers=string.Join(',',grnNumbers);inv.InvoiceType=type;inv.Status="RESUBMITTED";inv.IntegrationStatus="PENDING";inv.SubmissionDate=now;inv.UpdatedAt=now;}else{inv=new Invoice{Id=Guid.NewGuid(),VendorId=vendorId,InvoiceNumber=number,InvoiceDate=date,InvoiceAmount=amount,CurrencyCode="PKR",PoNumber=poNumber,GrnNumbers=string.Join(',',grnNumbers),InvoiceType=type,Status=draft?"DRAFT":"SUBMITTED",IntegrationStatus=draft?"NOT_STARTED":"PENDING",SubmissionDate=draft?null:now,CreatedBy=current.UserId,CreatedAt=now,UpdatedAt=now};db.Invoices.Add(inv);}db.InvoiceStatusHistory.Add(new InvoiceStatusHistory{InvoiceId=inv.Id,OldStatus=old,NewStatus=inv.Status,ChangedBy=current.UserId,ChangedAt=now,Source="PORTAL"});if(invoiceFile is not null)await AddDoc(db,inv.Id,invoiceFile,"INVOICE",current.UserId,now,ct);if(dcFile is not null)await AddDoc(db,inv.Id,dcFile,"DELIVERY_CHALLAN",current.UserId,now,ct);await db.SaveChangesAsync(ct);if(!draft)await db.Database.ExecuteSqlInterpolatedAsync($@"INSERT INTO integration.outbox_messages (id,event_type,aggregate_type,aggregate_id,payload,status,attempt_count,correlation_id,created_at) VALUES ({Guid.NewGuid()},{(resubmitId.HasValue?"InvoiceResubmitted":"InvoiceSubmitted")},{"Invoice"},{inv.Id},{System.Text.Json.JsonSerializer.Serialize(new{invoiceId=inv.Id,vendorId,oracleVendorId,poNumber,grnNumbers,invoiceNumber=inv.InvoiceNumber,invoiceDate=inv.InvoiceDate,invoiceAmount=inv.InvoiceAmount,invoiceType=inv.InvoiceType})}::jsonb,{"PENDING"},0,{Guid.NewGuid()},{now})",ct);await tx.CommitAsync(ct);log.LogInformation("Invoice {InvoiceId} saved. Draft={Draft}",inv.Id,draft);return Results.Ok(new{id=inv.Id,status=inv.Status,integrationStatus=inv.IntegrationStatus});}
 static void ValidateFile(IFormFile? file,IConfiguration cfg){if(file is null)return;var max=int.TryParse(cfg["MAX_UPLOAD_SIZE_MB"],out var m)?m:10;if(file.Length<=0||file.Length>max*1024L*1024L)throw new ApiException(400,$"Attachment must be between 1 byte and {max} MB.");var ext=Path.GetExtension(file.FileName).ToLowerInvariant();if(!new[]{".pdf",".png",".jpg",".jpeg"}.Contains(ext))throw new ApiException(400,"Only PDF, PNG, JPG and JPEG files are allowed.");}
 static async Task AddDoc(AppDbContext db,Guid invoiceId,IFormFile file,string type,Guid userId,DateTimeOffset now,CancellationToken ct){await using var ms=new MemoryStream();await file.CopyToAsync(ms,ct);var bytes=ms.ToArray();db.Documents.Add(new Document{Id=Guid.NewGuid(),InvoiceId=invoiceId,DocumentType=type,OriginalFileName=Path.GetFileName(file.FileName),ContentType=file.ContentType,FileExtension=Path.GetExtension(file.FileName).ToLowerInvariant(),FileSize=file.Length,FileHashSha256=Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(),FileContent=bytes,UploadedBy=userId,UploadedAt=now});}
}
